          "gabarito": "Exigir discussão multifatorial e proposta não estigmatizante; reconhecer que excesso energético e insuficiência de nutrientes não são a mesma coisa e podem ter relações complexas. Não pedir diagnóstico, restrição, metas de peso ou condutas de tratamento.",
